package com.simon.mytasks;
import org.json.*;
import android.os.Handler;

/** Runs the actual controller with deterministic host queue/storage/transport seams.
 * These are unit fakes, not an Android runtime or provider integration claim. */
public final class ConversationControllerTest {
 static int n,posts;static Store store;static ConversationController c;static String sentId;
 static void check(boolean ok,String why){n++;if(!ok)throw new AssertionError(why);}
 static JSONObject meta(String id,int revision,JSONObject request)throws Exception{return new JSONObject().put("id",id).put("revision",revision).put("title","Thread").put("archived",false).put("latest_request",request==null?JSONObject.NULL:request);}
 static JSONObject page(String id,JSONObject req)throws Exception{return new JSONObject().put("conversation",meta(id,2,req)).put("messages",new JSONArray()).put("has_more",false).put("before_cursor",JSONObject.NULL);}
 static void drain(){for(int i=0;i<30&&(Api.IO.hasWork()||Handler.hasImmediate());i++){Api.IO.drainOne();Handler.drainImmediate();}}
 static ConversationController fresh()throws Exception{store=new Store();return new ConversationController(store,store.account);}
 public static void main(String[] args)throws Exception{
  c=fresh();c.connected=true;c.foreground=true;c.visible="a";c.seed(meta("a",1,null));c.state.draft("a","hello");
  Api.transport=(m,p,b)->{if(m.equals("POST")){posts++;sentId=b.getString("request_id");JSONObject disk=new JSONObject(store.context.prefs.getString("state","{}"));check(disk.getJSONObject("pending").getJSONObject("a").getString("request_id").equals(sentId),"persisted identity before POST");return new JSONObject().put("conversation",meta("a",2,null)).put("request",new JSONObject().put("id",sentId).put("status","running")).put("user_message",new JSONObject().put("id",1).put("role","user").put("content","hello").put("request_id",sentId));}return page("a",null);};
  c.send("a","question");c.state.draft("a","follow up");c.visible="b";c.state.select("b");drain();
  check(posts==1&&c.state.draft("a").equals("follow up"),"acceptance cannot erase followup");check(c.state.selected().equals("b"),"acceptance cannot navigate wrong thread");check(!Handler.hasDelayed(),"no poll for hidden request");
  c.pause();ConversationController restarted=new ConversationController(store,store.account);check(restarted.state.pending("a").optString("request_id").equals(sentId),"restart envelope recovered");
  Api.transport=(m,p,b)->{check(!m.equals("POST"),"restart never automatically posts");return p.contains("/requests/")?new JSONObject().put("id",sentId).put("status","interrupted"):page("a",new JSONObject().put("id",sentId).put("status","interrupted"));};restarted.visible="a";restarted.resume();drain();check(restarted.state.pending("a").optString("status").equals("interrupted"),"server interrupted state authoritative");check(!Handler.hasDelayed(),"terminal state stops polling");
  c=fresh();c.connected=true;c.seed(meta("a",1,null));c.state.draft("a","persist first");store.context.prefs.fail=true;Api.transport=(m,p,b)->{throw new AssertionError("must not post without durable identity");};c.send("a","question");drain();check(!c.noticeFor("a").isEmpty()&&!Api.IO.hasWork(),"failed local persistence prevents network");check(c.state.draft("a").equals("persist first")&&!c.state.blocked("a"),"unsent text survives a local persistence failure without a phantom pending request");
  c=fresh();c.foreground=true;Api.transport=(m,p,b)->meta("created",1,null);c.create(null,()->{throw new AssertionError("must not reopen after navigation");});c.hide();drain();check(c.state.selected().isEmpty(),"late creation cannot hijack navigation");
  c=fresh();c.foreground=true;Api.transport=(m,p,b)->page("private",null);c.load("private",false);store.epoch="next account";drain();check(c.state.page("private")==null,"stale account response discarded");check(!store.context.prefs.getString("state","").contains("private"),"stale account not persisted");
  c=fresh();c.connected=true;c.seed(meta("a",1,null));c.state.draft("a","stale revision message");Api.transport=(m,p,b)->{if(m.equals("POST"))throw new Api.Failure(409);return page("a",null);};c.send("a","question");drain();check(!c.state.blocked("a"),"definitive admission conflict must not trap uncertain identity forever");check(c.state.pending("a").optString("status").equals("rejected"),"rejected admission distinct from accepted provider failure");c.reviewRetry("a");check(c.state.draft("a").equals("stale revision message"),"rejected message can be reviewed without an automatic resend");
  c=fresh();c.connected=true;c.seed(meta("a",1,null));c.state.draft("a","network uncertain");final String[] replay={""};final int[] networkPosts={0};Api.transport=(m,p,b)->{if(m.equals("POST")){networkPosts[0]++;if(networkPosts[0]==1){replay[0]=b.toString();throw new java.io.IOException("test timeout");}check(b.toString().equals(replay[0]),"explicit network replay preserves entire original identity and payload");return new JSONObject().put("conversation",meta("a",2,null)).put("request",new JSONObject().put("id",b.getString("request_id")).put("status","queued")).put("user_message",new JSONObject().put("id",1).put("content","network uncertain"));}return page("a",null);};c.send("a","question");drain();check(c.state.blocked("a")&&networkPosts[0]==1,"uncertain delivery blocks fresh identity and never auto retries");c.state.draft("a","newly typed");c.retryExact("a");drain();check(networkPosts[0]==2&&c.state.draft("a").equals("newly typed"),"explicit same identity replay preserves followup draft");
  c=fresh();c.foreground=true;c.visible="visible";Api.transport=(m,p,b)->page("visible",new JSONObject().put("id","server-request").put("status","queued"));c.load("visible",false);drain();check(Handler.hasDelayed(),"visible server pending request gets one bounded timer");c.pause();check(!Handler.hasDelayed(),"leaving foreground cancels pending timer");
  c=fresh();c.connected=true;c.seed(meta("a",1,null));c.state.draft("a","first");JSONObject first=c.state.prepare("a",1,"question");String firstId=first.getString("request_id");c.state.accept("a",new JSONObject().put("id",firstId).put("status","failed"));c.check("a",firstId);c.state.draft("a","second");JSONObject second=c.state.prepare("a",2,"question");Api.transport=(m,p,b)->new JSONObject().put("id",firstId).put("status","succeeded");drain();check(c.state.pending("a").getString("request_id").equals(second.getString("request_id")),"stale request status cannot overwrite newer identity");
  c=fresh();c.foreground=true;c.visible="a";Api.transport=(m,p,b)->{throw new java.io.IOException("test offline");};c.load("a",false);c.visible="b";drain();check(c.noticeFor("b").isEmpty(),"hidden thread errors cannot be displayed as another thread's failure");check(!c.noticeFor("a").isEmpty(),"hidden target retains its own safe diagnostic");
  c=fresh();c.state.draft("private-thread","private draft");c.save();c.close();check(!c.state.json().toString().contains("private draft"),"closed controllers release private memory and pending bindings");check(new ConversationController(store,store.account).state.draft("private-thread").equals("private draft"),"ordinary Activity close does not erase same-account durable drafts");
  c=fresh();c.foreground=true;c.visible="visible-b";Api.transport=(m,p,b)->page("visible-b",new JSONObject().put("id","b-request").put("status","queued"));c.load("visible-b",false);drain();check(Handler.hasDelayed(),"visible B starts pending timer");Api.transport=(m,p,b)->new JSONObject().put("id","hidden-a-request").put("status","running");c.check("hidden-a","hidden-a-request");drain();check(Handler.hasDelayed(),"hidden A callback must not cancel visible B polling");c.pause();
  System.out.println("ConversationControllerTest: "+n+" assertions passed");
 }
}
